Definition pv_ctx (m m1 : mem) (sp s0v rav : word) (q I R E lo : Z) (bs : list byte) (itv resv : Z) (E0 : ecv) (g : bool)
    (j8 : list byte) (tmp : list cell) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -48) [CB 8 j8]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -40) tmp
  /\ rw_cells rsegs m1 (bv_unsigned sp + -16) [C8 s0v; C8 rav]
  /\ rw_cells rsegs m1 I [C8 (wz itv)]
  /\ rw_cells rsegs m1 R [C4 (wz resv)]
  /\ rw_cells rsegs m1 E (ErrCodeCells E0)
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk rsegs m1 lo (bv_unsigned sp + -48)
  /\ bytes_at rsegs m1 q bs
  /\ munch (pv_W lo sp I R E) m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

Local Ltac open_pv CTX PURE :=
  destruct CTX as (FR0 & TMP & FRhi & IT & RES & EC & HC & XS & ST & WIN & MU & WM & MI);
  destruct PURE as (EOK & R0 & LO & IMG & QLO & QHI & ILO & IHI & RLO & RHI & ELO & EHI & DIR & DIE & DRE);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  unfold ErrCodeCells in EC;
  unfold pv_W, G_HTTP_CAT in *.
