(* [comment removed for export] *)
Lemma pv_out_short : forall bs, (length bs < 8)%nat -> pv_out bs = mkPV 0 None (Some (HE_NEED_MORE, LOC_PV_NM)).
Proof.
  intros bs H.
  destruct bs as [|c0 [|c1 [|c2 [|c3 [|c4 [|c5 [|c6 [|c7 rest]]]]]]]]; try reflexivity. cbn in H. lia.
Qed.

Lemma list_split8 : forall (bs : list byte), (8 <= length bs)%nat ->
  exists c0 c1 c2 c3 c4 c5 c6 c7 rest, bs = c0 :: c1 :: c2 :: c3 :: c4 :: c5 :: c6 :: c7 :: rest.
Proof.
  intros bs H.
  destruct bs as [|c0 [|c1 [|c2 [|c3 [|c4 [|c5 [|c6 [|c7 rest]]]]]]]]; cbn in H; try lia.
  exists c0, c1, c2, c3, c4, c5, c6, c7, rest. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma pv_digit_yes : forall c, 48 <= c <= 57 -> negb (bv_ltu (Z_to_bv 64 (c + -48)) (Z_to_bv 64 10)) = false.
Proof. intros c Hc. unfold bv_ltu. rewrite !unsigned_lit by lia. apply Bool.negb_false_iff. apply Z.ltb_lt. lia. Qed.
Lemma pv_digit_no : forall c, 0 <= c < 256 -> ~ (48 <= c <= 57) -> negb (bv_ltu (Z_to_bv 64 (c + -48)) (Z_to_bv 64 10)) = true.
Proof.
  intros c Hc Hd. unfold bv_ltu. apply Bool.negb_true_iff. apply Z.ltb_ge. rewrite (unsigned_lit 10) by lia.
  destruct (Z.lt_ge_cases c 48).
  - rewrite unsigned_lit_wrap. replace ((c + -48) mod 2 ^ 64) with (2^64 + c - 48) by (Z.div_mod_to_equations; lia). lia.
  - rewrite unsigned_lit by lia. lia.
